import polars as pl

def dataframes_equal(df1: pl.DataFrame, df2: pl.DataFrame) -> bool:
    """
    Check if two Polars DataFrames are exactly equal (same schema and same values).

    Args:
        df1: First DataFrame
        df2: Second DataFrame

    Returns:
        True if both DataFrames have the same schema and values, False otherwise
    """
    return df1.equals(df2)


# Example usage
if __name__ == "__main__":
    df1 = pl.DataFrame({
        "a": [1, 2, 3],
        "b": ["x", "y", "z"]
    })

    df2 = pl.DataFrame({
        "a": [1, 2, 3],
        "b": ["x", "y", "z"]
    })

    df3 = pl.DataFrame({
        "a": [1, 2, 4],
        "b": ["x", "y", "z"]
    })

    df4 = pl.DataFrame({
        "a": [1, 2, 3],
    })

    print(f"df1 == df2: {dataframes_equal(df1, df2)}")  # True
    print(f"df1 == df3: {dataframes_equal(df1, df3)}")  # False (different values)
    print(f"df1 == df4: {dataframes_equal(df1, df4)}")  # False (different schema)

